                  <div className="h-px bg-slate-50 my-1 mx-4" />
                  <button onClick={handleResetCanvas} className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-red-600 hover:bg-red-50 transition-colors text-left">
                    <Trash2 size={16} />
