                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-0.5">
                      {t(type === 'tag' ? 'tags' : type === 'table' ? 'data_table' : type === 'logic' ? 'logic_node' : 'link_classification')}
