      cardType: NodeCardType.TABLE, 
      categoryId: 'cat-std',
      tags: ['tag-ext'],
      columns: [
        { id: 'c12', name: 'Report_ID', typeId: 'ft-text', isKey: true },
        { id: 'c13', name: 'Period', typeId: 'ft-text' },
        { id: 'c14', name: 'Total_VAT_Collected', typeId: 'ft-number' }
