                  {bulletPoints.map((p, idx) => (
                    <div 
                      key={idx} 
                      draggable
                      onDragStart={() => handleBulletDragStart(idx)}
                      onDragOver={(e) => handleBulletDragOver(e, idx)}
                      onDragEnd={handleDragEnd}
