        label: `New ${type.toLowerCase()}`, cardType: type, categoryId: defaultCatId,
        columns: type === NodeCardType.TABLE ? [{ id: '1', name: 'New Field', isKey: false }] : [],
        description: '', bulletPoints: [], comment: '', dataSourceId: '', tags: []
      },
