    }))), "Nodes");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(edges.map(e => ({
      ID: e.id, Source: e.source, Target: e.target, Label: e.label || '', TypeID: e.data?.typeId || ''
    }))), "Edges");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(settings.tableCategories), "TableCategories");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(settings.logicCategories), "LogicCategories");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(settings.connectionTypes), "ConnectionTypes");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(settings.dataSources), "DataSources");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(settings.fieldTypes), "FieldTypes");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(settings.tags || []), "Tags");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet([appearance]), "Appearance");
    const filename = `WhiteBox_Project_${Date.now()}.xlsx`;
    XLSX.writeFile(wb, filename);
    setOpenMenuType(null);
  };

  const isNodeVisible = useCallback((node: Node<NodeData>) => {
    const { data } = node;
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      if (!data.label.toLowerCase().includes(q) && !data.description?.toLowerCase().includes(q)) return false;
    }
    return true;
  }, [searchQuery]);

  const filteredNodes = useMemo(() => nodes.filter(isNodeVisible), [nodes, isNodeVisible]);

  const nodesWithActions = useMemo(() => filteredNodes.map(n => ({
    ...n, data: { ...n.data, onEdit: setEditingNode, onDelete: (id: string) => setNodes(nds => nds.filter(node => node.id !== id)), onDuplicate: handleDuplicateNode, settings, appearance }
  })), [filteredNodes, settings, appearance, handleDuplicateNode]);

  const edgesWithActions = useMemo(() => edges.map(e => ({
    ...e, data: { ...e.data, onEdit: setEditingEdge, onDelete: (id: string) => setEdges(eds => eds.filter(edge => edge.id !== id)), settings }
  })), [edges, settings]);

  return (
    <div className="w-full h-full bg-slate-50 relative overflow-hidden" style={{ backgroundColor: appearance.canvasBgColor }}>
      <main className="w-full h-full relative">
        <div className="absolute inset-x-0 top-0 p-4 flex items-center justify-between pointer-events-none z-30" ref={toolbarRef}>
          <div className="flex items-center gap-2 pointer-events-auto">
            <div className="relative">
              <button onClick={() => setOpenMenuType(openMenuType === 'add' ? null : 'add')} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 transition-all">
