            {openMenuType === 'io' && (
                <div className="absolute top-full left-14 mt-2 w-48 bg-white rounded-xl shadow-xl border border-slate-100 py-1 overflow-hidden z-50 pointer-events-auto">
                  <button onClick={exportToExcel} className="w-full flex items-center gap-2 px-4 py-2 text-sm font-bold text-slate-700 hover:bg-slate-50 transition-colors"><Download size={16} />{t('export_project')}</button>
                  <button onClick={handleResetCanvas} className="w-full flex items-center gap-2 px-4 py-2 text-sm font-bold text-red-600 hover:bg-red-50 transition-colors"><Trash2 size={16} />{t('reset_canvas')}</button>
                </div>
            )}
            <div className="h-6 w-px bg-slate-300 mx-1" />
            <button onClick={() => setShowStudioSettings({ initialTab: 'general' })} className="p-2 bg-slate-900 text-white rounded-full shadow-lg hover:bg-slate-800 transition-all"><Settings2 size={20} /></button>
            <button 
              onClick={handleAutoAlign} 
              className={`flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-full shadow-lg hover:bg-blue-700 transition-all ${viewType !== 'canvas' ? 'opacity-60 cursor-default' : ''}`}
            >
              <Maximize size={18} /> <span className="text-sm font-bold">{t('auto_align')}</span>
            </button>
          </div>
          <div className="flex items-center gap-2 pointer-events-auto">
             <button onClick={() => setViewType(viewType === 'canvas' ? 'catalog' : 'canvas')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-full shadow-lg hover:bg-indigo-700 transition-all">
              {viewType === 'canvas' ? <LayoutList size={20} /> : <MapIcon size={20} />}
              <span className="text-sm font-bold">{t('view_swap')}</span>
            </button>
          </div>
        </div>

        {viewType === 'canvas' ? (
          <>
            <ReactFlow nodes={nodesWithActions} edges={edgesWithActions} onNodesChange={onNodesChange} onEdgesChange={onEdgesChange} onConnect={onConnect} nodeTypes={nodeTypes} edgeTypes={edgeTypes} fitView fitViewOptions={{ padding: CANVAS_PADDING }} className="bg-transparent">
              <Background color="#cbd5e1" variant={BackgroundVariant.Dots} />
              <Controls />
            </ReactFlow>
            <Legend settings={settings} appearance={appearance} onUpdateAppearance={setAppearance} />
          </>
        ) : (
          <div className="w-full h-full overflow-y-auto px-8 pt-24">
            <div className="max-w-4xl mx-auto mb-10"><input type="text" placeholder={t('search_placeholder')} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full p-4 bg-white rounded-2xl border border-slate-200 shadow-sm focus:ring-2 focus:ring-blue-500 outline-none text-lg font-medium" /></div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 max-w-7xl mx-auto">
              {filteredNodes.map(n => (
                <div key={n.id} className="relative group">
                    <BlueprintCard id={n.id} data={{ ...n.data, settings, appearance, onEdit: setEditingNode, onDelete: (id: string) => setNodes(nds => nds.filter(node => node.id !== id)), onDuplicate: handleDuplicateNode }} type="blueprintNode" dragging={false} zIndex={1} isConnectable={false} xPos={0} yPos={0} selected={false} />
                    <button onClick={() => handleLocateOnCanvas(n.id)} className="absolute top-2 right-14 p-2 bg-white text-blue-600 rounded-lg shadow border border-slate-100 opacity-0 group-hover:opacity-100 transition-all"><Crosshair size={14} /></button>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {editingNode && <EditorModal node={nodes.find(n => n.id === editingNode)!} settings={settings} onClose={() => setEditingNode(null)} onSave={(data) => handleSaveNode(editingNode, data)} language={appearance.language} />}
      {editingEdge && <EdgeEditorModal edge={edges.find(e => e.id === editingEdge)!} settings={settings} onClose={() => setEditingEdge(null)} onSave={(data) => handleSaveEdge(editingEdge, data)} language={appearance.language} />}
      {showStudioSettings && <StudioSettingsModal settings={settings} appearance={appearance} initialTab={showStudioSettings.initialTab} onClose={() => setShowStudioSettings(null)} onSave={(s, a) => { setSettings(s); setAppearance(a); }} />}
    </div>
  );
}

export default function App() {
  return (
    <ReactFlowProvider>
      <BlueprintStudio />
    </ReactFlowProvider>
  );
}

